pub(super) fn generated_builtin_arity(name: &str) -> Option<(i64, i64)> {
    let index = GENERATED_BUILTIN_ARITIES
        .binary_search_by_key(&name, |(candidate, _, _)| *candidate)
        .ok()?;
    let (_, minimum, maximum) = GENERATED_BUILTIN_ARITIES[index];
    Some((minimum, maximum))
}

